<?php
error_reporting(E_ALL);
require_once __DIR__.'/../domains/phucthinhsolar.com/public_html/libraries/pts_public_project_detail_api.php';
function projectDetailAssert($condition, $message) { if(!$condition) throw new RuntimeException($message); echo 'PASS: ', $message, "\n"; }
$row = array('id'=>7,'namevi'=>'Công trình <b>thật</b>','slugvi'=>'cong-trinh-that','descvi'=>'<p>Mô tả CMS</p>','contentvi'=>'<script>alert(1)</script>','photo'=>'cover.jpg','status'=>'hienthi','category_id'=>3,'category_name'=>'Hộ gia đình','category_slug'=>'ho-gia-dinh','tenkhachhang'=>'Khách CMS','address'=>'Địa chỉ CMS','project_start_date'=>'2026-01-02','project_end_date'=>'2026-02-03','_pts_cover'=>'/upload/news/cover.jpg');
$gallery = array(array('type'=>'image','src'=>'/upload/news/gallery.jpg','caption'=>'Ảnh CMS'),array('type'=>'video','src'=>'/upload/news/video.jpg','href'=>'https://video.example/watch','caption'=>'Video CMS'));
$related = array(array('id'=>9,'name'=>'Thiết bị CMS','slug'=>'thiet-bi-cms','url'=>'/san-pham/thiet-bi-cms','code'=>'PT-9','image'=>'/upload/product/device.jpg'));
$payload = ptsProjectDetailPayload($row, $gallery, $related, array('project'=>'legacy /cong-trinh-that/'));
projectDetailAssert($payload['project']['url'] === '/cong-trinh-that/' && $payload['project']['title'] === 'Công trình thật', 'plain text và canonical URL');
projectDetailAssert($payload['project']['client'] === 'Khách CMS' && $payload['project']['startDate'] === '2026-01-02', 'field chi tiết chỉ lấy từ CMS');
projectDetailAssert($payload['seo']['title'] === 'Công trình thật | Phúc Thịnh Solar' && $payload['seo']['description'] === '' && $payload['seo']['keywords'] === '', 'SEO fallback khớp title legacy và không tự bịa description');
$adminSeo = ptsProjectDetailPayload($row, array(), array(), array(), array(), null, array('titlevi'=>'SEO do Admin nhập', 'descriptionvi'=>'<p>Mô tả SEO CMS</p>', 'keywordsvi'=>'solar, CMS'));
projectDetailAssert($adminSeo['seo']['title'] === 'SEO do Admin nhập | Phúc Thịnh Solar' && $adminSeo['seo']['description'] === 'Mô tả SEO CMS' && $adminSeo['seo']['keywords'] === 'solar, CMS', 'SEO title/description/keywords được chiếu từ Admin');
$brandedSeo = ptsProjectDetailSeoDto('Tên dự án', array('titlevi'=>'Tên dự án | Phúc Thịnh Solar', 'descriptionvi'=>'0'));
projectDetailAssert($brandedSeo['title'] === 'Tên dự án | Phúc Thịnh Solar' && $brandedSeo['description'] === '', 'không lặp hậu tố thương hiệu và giữ ngữ nghĩa empty() PHP');
projectDetailAssert($payload['content']['format'] === 'sanitized-html' && $payload['content']['sanitizedBy'] === 'pts_public_richtext' && strpos($payload['content']['html'], '<script') === false && strpos(json_encode($payload), '<script') === false, 'content da qua pts_public_richtext, khong lo script tho');
projectDetailAssert($payload['project']['relatedEquipment'][0]['url'] === '/san-pham/thiet-bi-cms', 'related equipment giữ canonical product URL');
projectDetailAssert($payload['project']['relatedProjects'] === array() && $payload['project']['cta'] === null, 'related projects / CTA không tự dựng khi chưa chiếu dữ liệu');
projectDetailAssert(ptsProjectDetailRelatedProjectDto(array('id'=>13,'namevi'=>'Dự án cùng nhóm','slugvi'=>'du-an-cung-nhom','status'=>'hienthi'))['url'] === '/du-an-cung-nhom/', 'dự án liên quan giữ URL canonical và text sạch');
projectDetailAssert(count(ptsProjectDetailTrustDto(array())) === 3 && ptsProjectDetailTrustDto(array())[0]['faIcon'] === 'fa-headset', 'CTA fallback khớp ba mục tin cậy đã duyệt ở project hub');
projectDetailAssert(ptsProjectDetailTrustDto(array(array('status'=>'hienthi','namevi'=>'Tư vấn CMS','photo'=>'trust.png')))[0]['label'] === 'Tư vấn CMS', 'CTA ưu tiên trust item đang hiển thị từ Admin');
$cta = array('eyebrow'=>'', 'title'=>'Tư vấn', 'description'=>'', 'buttonLabel'=>'Liên hệ', 'image'=>'', 'hotline'=>'', 'trust'=>ptsProjectDetailTrustDto(array(array('status'=>'hienthi','namevi'=>'Tư vấn CMS'))));
$withCta = ptsProjectDetailPayload($row, array(), array(), array(), array(), $cta);
projectDetailAssert($withCta['project']['cta']['trust'][0]['label'] === 'Tư vấn CMS', 'project detail DTO giữ các mục trust đã chiếu vào CTA');
projectDetailAssert(ptsProjectDetailProductDto(array('id'=>11,'namevi'=>'Biến tần thật','slugvi'=>'bien-tan-that','status'=>'hienthi'))['url'] === '/san-pham/bien-tan-that', 'ptsProjectDetailProductDto() tu xay url cung khong co dau / cuoi');
projectDetailAssert(ptsProjectDetailSlug('../secret') === '' && ptsProjectDetailSlug('Good Slug') === '', 'chặn traversal và slug sai');
$hidden = $row; $hidden['status'] = ''; projectDetailAssert(ptsProjectDetailPayload($hidden, array(), array()) === null, 'record ẩn không được hồi sinh');
$endpoint = realpath(__DIR__.'/../domains/phucthinhsolar.com/public_html/api/pts_v1_project_detail.php');
$command = escapeshellarg(PHP_BINARY).' -r '.escapeshellarg('$_SERVER["REQUEST_METHOD"] = "POST"; require '.var_export($endpoint, true).';').' 2>&1';
projectDetailAssert(strpos((string)shell_exec($command), 'METHOD_NOT_ALLOWED') !== false, 'endpoint từ chối method khác GET');
echo "PASS: PTS public project detail API contract\n";
